import '../npc/npc_content.dart';
import '../state/player_event_journal.dart';
import '../state/runtime_game_state.dart';
import 'dialogue_model.dart';

/// Stable priority resolver for entry nodes in one finite dialogue graph.
class DialogueResolver {
  const DialogueResolver(this.nodes, {this.entryNodeIds});

  final List<DialogueNode> nodes;
  final List<String>? entryNodeIds;

  DialogueNode? resolve(
    NpcRelationshipState relationship, {
    PlayerEventJournal? journal,
    double activePlaySeconds = 0,
  }) {
    final entries = entryNodeIds;
    final allowed = entries?.toSet();
    final matches =
        nodes
            .where(
              (node) =>
                  node.npcId == relationship.npcId &&
                  (allowed == null || allowed.contains(node.id)) &&
                  node.conditions.matches(
                    relationship,
                    journal: journal,
                    activePlaySeconds: activePlaySeconds,
                  ),
            )
            .toList()
          ..sort((left, right) {
            final priority = right.priority.compareTo(left.priority);
            return priority != 0 ? priority : left.id.compareTo(right.id);
          });
    return matches.isEmpty ? null : matches.first;
  }
}
